PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "username" varchar not null, "phone" varchar not null, "country" varchar not null, "address" varchar, "id_type" varchar not null, "id_document" varchar not null, "total_usdt" numeric not null default '0', "conversion_ngn" numeric not null default '0', "asset_balance" numeric not null default '0', "investment_balance" numeric not null default '0', "ai_investment_balance" numeric not null default '0', "role" varchar not null default 'user', "id_document_front" varchar, "id_document_back" varchar, "face_image" varchar, "id_status" varchar check ("id_status" in ('pending', 'verified', 'rejected')) not null default 'pending', "face_match_score" float, "totp_secret" varchar, "two_fa_enabled" tinyint(1) not null default '0', "avatar" varchar, "bank_name" varchar, "account_name" varchar, "account_number" varchar, "paypal_email" varchar);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "personal_access_tokens" ("id" integer primary key autoincrement not null, "tokenable_type" varchar not null, "tokenable_id" integer not null, "name" text not null, "token" varchar not null, "abilities" text, "last_used_at" datetime, "expires_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "wallets" ("id" integer primary key autoincrement not null, "user_id" integer not null, "coin" varchar not null, "address" varchar not null, "xpub" varchar, "balance" numeric not null default '0', "created_at" datetime, "updated_at" datetime, "name" varchar, "symbol" varchar, "network" varchar, "usd_value" numeric, "trading_mode" varchar not null default 'crypto', "margin" numeric not null default '0', "leverage" integer not null default '1', foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "staking_plans" ("id" integer primary key autoincrement not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "user_stakes" ("id" integer primary key autoincrement not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "push_subscriptions" ("id" integer primary key autoincrement not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "chats" ("id" integer primary key autoincrement not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "futures_balances" ("id" integer primary key autoincrement not null, "user_id" integer not null, "margin_balance" numeric not null default '0', "wallet_balance" numeric not null default '0', "unrealized_pnl" numeric not null default '0', "realized_pnl_today" numeric not null default '0', "realized_pnl_percent" numeric not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "futures_positions" ("id" integer primary key autoincrement not null, "user_id" integer not null, "symbol" varchar not null, "type" varchar not null default 'perpetual', "side" varchar check ("side" in ('B', 'S')) not null, "leverage" integer not null default '10', "size" numeric not null default '0', "margin_usdt" numeric not null default '0', "pnl_usdt" numeric not null default '0', "roi" numeric not null default '0', "margin_ratio" numeric not null default '0', "entry_price" numeric not null default '0', "mark_price" numeric not null default '0', "liquidation_price" numeric not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "investment_payments" ("id" integer primary key autoincrement not null, "user_id" integer not null, "plan_name" varchar not null, "amount" numeric not null, "profit_percent" numeric not null, "expected_profit" numeric not null default '0', "duration" varchar not null, "status" varchar check ("status" in ('pending', 'active', 'completed', 'cancelled')) not null default 'pending', "start_date" datetime, "end_date" datetime, "transaction_id" varchar, "created_at" datetime, "updated_at" datetime, "selar_payment_link" varchar, "paid_out" numeric not null default '0', "last_payout_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "p2_p_vendors" ("id" integer primary key autoincrement not null, "name" varchar not null, "avatar" varchar, "currency" varchar not null, "price" numeric not null, "min_limit" numeric not null, "max_limit" numeric not null, "payment_methods" text not null, "quantity" numeric not null, "trades" integer not null default '0', "completion" numeric not null default '0', "verified" tinyint(1) not null default '0', "online" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "rewards" ("id" integer primary key autoincrement not null, "user_id" integer not null, "title" varchar not null, "desc" varchar not null, "amount" varchar not null, "status" varchar check ("status" in ('Active', 'Completed')) not null default 'Active', "icon" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "orders" ("id" integer primary key autoincrement not null, "user_id" integer not null, "pair" varchar not null, "side" varchar check ("side" in ('buy', 'sell')) not null, "type" varchar check ("type" in ('limit', 'market', 'stop')) not null, "price" numeric, "amount" numeric not null, "trigger_price" numeric, "filled" numeric not null default '0', "status" varchar check ("status" in ('pending', 'filled', 'partial', 'cancelled')) not null default 'pending', "order_id" varchar not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "wallet_logs" ("id" integer primary key autoincrement not null, "user_id" integer not null, "coin" varchar not null, "amount" numeric not null, "usd_value" numeric, "action" varchar not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "deposits" ("id" integer primary key autoincrement not null, "user_id" integer not null, "coin" varchar not null, "amount" numeric not null, "usd_amount" numeric, "status" varchar check ("status" in ('pending', 'approved', 'rejected')) not null default 'pending', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "withdrawals" ("id" integer primary key autoincrement not null, "user_id" integer not null, "coin" varchar not null, "amount" numeric not null, "usd_amount" numeric, "status" varchar check ("status" in ('pending', 'approved', 'rejected')) not null default 'pending', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "api_keys" ("id" integer primary key autoincrement not null, "name" varchar not null, "key" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "security_logs" ("id" integer primary key autoincrement not null, "user_id" integer, "action" varchar not null, "ip" varchar, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "settings" ("id" integer primary key autoincrement not null, "key" varchar not null, "value" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "user_kycs" ("id" integer primary key autoincrement not null, "user_id" integer not null, "status" varchar not null default 'pending', "id_type" varchar, "id_document_front" varchar, "id_document_back" varchar, "selfie" varchar, "face_match_score" varchar, "rejection_reason" varchar, "verified_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "notifications" ("id" varchar not null, "type" varchar not null, "notifiable_type" varchar not null, "notifiable_id" integer not null, "data" text not null, "read_at" datetime, "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE TABLE IF NOT EXISTS "tickers" ("id" integer primary key autoincrement not null, "symbol" varchar not null, "type" varchar check ("type" in ('crypto', 'forex', 'futures')) not null, "last_price" numeric not null default '0', "price_change_percent" numeric not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "ai_investments_temp" ("id" integer primary key autoincrement not null, "user_id" integer not null, "pair" varchar not null, "type" varchar check ("type" in ('market', 'limit', 'stop')) not null, "side" varchar check ("side" in ('buy', 'sell')) not null, "amount" numeric not null, "duration_days" integer not null default '7', "expected_return" numeric, "status" varchar check ("status" in ('active', 'completed', 'failed')) not null default 'active', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "ai_investments" ("id" integer primary key autoincrement not null, "user_id" integer not null, "pair" varchar not null, "type" varchar check ("type" in ('market', 'limit', 'stop')) not null, "side" varchar check ("side" in ('buy', 'sell')) not null, "amount" numeric not null, "duration_days" integer not null default '7', "expected_return" numeric, "status" varchar check ("status" in ('active', 'completed', 'failed')) not null default 'active', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "investment_plans" ("id" integer primary key autoincrement not null, "plan_name" varchar not null, "min_amount" numeric not null default '0', "profit_percent" numeric not null default '0', "duration" integer not null, "selar_payment_link" varchar, "status" varchar check ("status" in ('active', 'inactive')) not null default 'active', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "transactions" ("id" integer primary key autoincrement not null, "sender_id" integer not null, "receiver_id" integer not null, "amount" numeric not null, "type" varchar not null default 'transfer', "status" varchar not null default 'completed', "description" text, "created_at" datetime, "updated_at" datetime, foreign key("sender_id") references "users"("id") on delete cascade, foreign key("receiver_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "positions" ("id" integer primary key autoincrement not null, "user_id" integer not null, "pair" varchar not null, "side" varchar not null, "entry_price" numeric not null, "size" numeric not null, "margin_used" numeric not null default '0', "leverage" integer not null default '1', "unrealized_pnl" numeric not null default '0', "mode" varchar not null default 'crypto', "status" varchar not null default 'open', "created_at" datetime, "updated_at" datetime, "exit_price" numeric, "pnl" numeric, "closed_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "ledgers" ("id" integer primary key autoincrement not null, "user_id" integer not null, "type" varchar not null, "amount" numeric not null default '0', "pnl" numeric, "symbol" varchar, "mode" varchar, "note" varchar, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE INDEX "personal_access_tokens_tokenable_type_tokenable_id_index" on "personal_access_tokens" ("tokenable_type", "tokenable_id");
CREATE UNIQUE INDEX "personal_access_tokens_token_unique" on "personal_access_tokens" ("token");
CREATE INDEX "personal_access_tokens_expires_at_index" on "personal_access_tokens" ("expires_at");
CREATE UNIQUE INDEX "users_username_unique" on "users" ("username");
CREATE UNIQUE INDEX "investment_payments_transaction_id_unique" on "investment_payments" ("transaction_id");
CREATE UNIQUE INDEX "orders_order_id_unique" on "orders" ("order_id");
CREATE UNIQUE INDEX "api_keys_key_unique" on "api_keys" ("key");
CREATE UNIQUE INDEX "settings_key_unique" on "settings" ("key");
CREATE INDEX "notifications_notifiable_type_notifiable_id_index" on "notifications" ("notifiable_type", "notifiable_id");
CREATE UNIQUE INDEX "investment_plans_plan_name_unique" on "investment_plans" ("plan_name");
CREATE INDEX "wallets_user_id_symbol_trading_mode_index" on "wallets" ("user_id", "symbol", "trading_mode");
CREATE INDEX "positions_user_id_pair_status_index" on "positions" ("user_id", "pair", "status");
COMMIT;
